function curated(){const lead=['scroll-layered-parallax','svg-displacement','easing-back-out','type-text-path','sound-pop','layout-container-query'];const groups=categories.map(c=>all.filter(e=>e.category===c[0]));const result=lead.map(id=>byId.get(id));for(let i=0;i<Math.max(...groups.map(g=>g.length));i++)for(const group of groups)if(group[i])result.push(group[i]);return [...new Map(result.map(e=>[e.id,e])).values()]}
