function optionsHTML(selected){return easingOptions.map(([v,n])=>`<option value="${v}" ${v===selected?'selected':''}>${n}</option>`).join('')+(!easingOptions.some(([v])=>v===selected)?`<option value="${esc(selected)}" selected>この表現の初期設定</option>`:'')}

function openDetail(id){const trigger=detail.open?detailOrigin:document.activeElement;const e=byId.get(id);if(!e)return;releaseDetail();detailOrigin=trigger;const isMotion=e.type==='motion';detail.innerHTML=`<div class="dialog-top"><span>${categoryData(e.category)[3]} / ${String(all.indexOf(e)+1).padStart(3,'0')}</span><button class="close-button" aria-label="閉じる">×</button></div><div class="detail-body"><section><div class="detail-stage" id="detail-stage"></div>${isMotion?`<div class="detail-playbar"><button id="play-detail">❚❚ 停止</button><button id="replay-detail" aria-label="最初から再生">↻</button><input id="scrub" type="range" min="0" max="100" value="0" aria-label="アニメーションの進行位置"></div><div class="detail-controls"><label class="control-field">時間 <span><output id="duration-out">${e.duration}</output> ms</span><input id="duration" type="range" min="200" max="4000" step="50" value="${e.duration}"></label><label class="control-field">動きの緩急<select id="easing">${optionsHTML(e.easing)}</select></label><label class="control-field">表示する文字<input id="demo-text" type="text" value="good" maxlength="18" ${e.visual!=='word'?'disabled':''}></label><label class="control-field">色<input type="color" id="demo-color" value="${colorways[all.indexOf(e)%6][1]}"></label></div><label class="small-note"><input type="checkbox" id="demo-loop" checked> 繰り返す</label>`:`<p class="small-note">${['ui','interaction','three','layout'].includes(e.category)?'見本の中をタップ・操作して、変化を試せます。':e.type==='sound'?'再生ボタンから聴いてみてください。音量も調整できます。':e.type==='interactive'?'見本の中のボタンやスクロールを操作して試せます。':'実際のHTMLとCSSで描画しています。'}</p>`}<div class="detail-tabs"><button class="active" data-detail-tab="code">実装コード</button><button data-detail-tab="brief">依頼文</button></div><pre class="code-block" id="detail-code"></pre><div class="button-row"><button class="primary-button" id="copy-detail">コピーする ↗</button><button class="secondary-button" id="share-detail">共有する ↗</button></div></section><section><p class="eyebrow">Know the expression</p><h2 class="detail-title">${esc(e.name)}</h2><p class="detail-jp">${esc(e.ja)}</p><p class="detail-description">${esc(e.description)}</p><h3 class="detail-section-label">こんなときに</h3><p class="detail-info">${esc(e.use)}</p><div class="detail-note">${esc(e.tip)}</div><div class="experiment-prompt"><h3>ひとつ試すなら</h3><p>${esc(promptFor(e.id))}</p></div><div class="detail-tags">${e.tags.map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="button-row" style="margin-top:24px"><button class="secondary-button" id="detail-save">${favorites.has(id)?'♥ 保存済み':'♡ コレクションに保存'}</button><button class="secondary-button" id="detail-compare">⊕ 比較に加える</button></div><div class="detail-links"><a href="expressions/${e.id}.html">この表現の個別ページ ↗</a><a href="${esc(e.source)}" target="_blank" rel="noopener noreferrer">仕組みを公式資料で読む ↗</a></div><section class="discovery-next"><h3>この表現から、次の発見へ</h3>${connections(id).map(r=>`<button data-discover="${r.entry.id}"><strong>${esc(r.entry.name)} ↗</strong><span>${esc(r.reason)}</span></button>`).join('')}</section><p class="small-note">表現名は通称・説明のための名称です。実装仕様の名称とは異なる場合があります。デモはこの図鑑のオリジナルです。</p></section></div>`;
 const demo=createDemo($('#detail-stage'),e,{manual:true}),settings={duration:e.duration,easing:e.easing,iterations:Infinity};let tab='code',text='good',accent=colorways[all.indexOf(e)%6][1];const brief=()=>`${e.name}（${e.ja}）を使ってください。${e.description}${isMotion?`再生時間は${settings.duration}ms、イージングは${settings.easing}、再生は${settings.iterations===Infinity?'繰り返し':'1回'}です。${e.visual==='word'?`表示する文字は「${text}」。`:''}基本色は${accent}。`:''}${e.use}動きを抑える設定にも対応してください。`;
 const updateCode=()=>{$('#detail-code').textContent=tab==='code'?(isMotion?motionCode(e,settings,text,accent):e.code):brief()};updateCode();
 $('.close-button',detail).onclick=()=>detail.close();$('#copy-detail').onclick=()=>copy($('#detail-code').textContent);$('#share-detail').onclick=()=>sharePage({title:`${e.name} — gooooooooood expression`,text:e.ja,url:new URL(`expressions/${e.id}.html`,location.href).href},toast);$('#detail-save').onclick=()=>{toggleFavorite(id);$('#detail-save').textContent=favorites.has(id)?'♥ 保存済み':'♡ コレクションに保存'};$('#detail-compare').onclick=()=>{toggleCompare(id);toast(comparison.includes(id)?'比較に加えました':'比較から外しました')};$$('[data-detail-tab]',detail).forEach(b=>b.onclick=()=>{tab=b.dataset.detailTab;$$('[data-detail-tab]',detail).forEach(n=>n.classList.toggle('active',n===b));updateCode()});
 $$('[data-discover]',detail).forEach(b=>b.onclick=()=>openDetail(b.dataset.discover));
 let raf;
 if(isMotion){const a=demo.animation;$('#play-detail').textContent=a.playState==='paused'?'▷ 再生':'❚❚ 停止';$('#play-detail').onclick=()=>{if(a.playState==='running'){a.pause();$('#play-detail').textContent='▷ 再生'}else{a.play();$('#play-detail').textContent='❚❚ 停止'}};$('#replay-detail').onclick=()=>{demo.replay();$('#play-detail').textContent='❚❚ 停止'};$('#scrub').oninput=ev=>{a.pause();a.currentTime=settings.duration*Number(ev.target.value)/100;$('#play-detail').textContent='▷ 再生'};$('#duration').oninput=ev=>{settings.duration=Number(ev.target.value);$('#duration-out').textContent=settings.duration;demo.update(settings);updateCode()};$('#easing').onchange=ev=>{settings.easing=ev.target.value;demo.update(settings);updateCode()};$('#demo-loop').onchange=ev=>{settings.iterations=ev.target.checked?Infinity:1;demo.update(settings);demo.replay();updateCode()};$('#demo-text').oninput=ev=>{text=ev.target.value;demo.setText(text);updateCode()};$('#demo-color').oninput=ev=>{accent=ev.target.value;demo.setAccent(accent);updateCode()};const tick=()=>{if(!detail.open)return;if(a.playState==='running')$('#scrub').value=(a.currentTime%settings.duration)/settings.duration*100;raf=requestAnimationFrame(tick)};if(!detail.open)detail.showModal();raf=requestAnimationFrame(tick)}else if(!detail.open)detail.showModal();
 releaseDetail=()=>{cancelAnimationFrame(raf);demo.destroy();demos.delete(demo)};detail.onclose=()=>{releaseDetail();releaseDetail=()=>{};detail.innerHTML='';if(trigger?.isConnected)trigger.focus({preventScroll:true})};
}
for(const dialog of $$('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function openComparison(){if(comparison.length<2)return;const dialog=$('#compare-dialog');dialog.innerHTML=`<div class="dialog-top"><span>COMPARE · 違いを、同じ条件で。</span><button class="close-button" aria-label="比較を閉じる">×</button></div><div class="compare-grid" style="grid-template-columns:repeat(${comparison.length},minmax(0,1fr))">${comparison.map(id=>{const e=byId.get(id);return `<section class="compare-item"><div class="compare-stage" data-compare-stage="${id}"></div><h3>${esc(e.name)}</h3><p>${esc(e.ja)}</p><p>${esc(e.description)}</p></section>`}).join('')}</div><div class="compare-controls"><button class="primary-button" id="compare-replay">↻ 同時に再生</button><label>再生速度 <select id="compare-speed"><option value="0.25">0.25倍</option><option value="0.5">0.5倍</option><option value="1" selected>1倍</option><option value="2">2倍</option></select></label><label><input type="checkbox" id="compare-same" checked> 時間を1500msに揃える</label></div>`;const ds=$$('[data-compare-stage]').map(n=>createDemo(n,byId.get(n.dataset.compareStage),{duration:1500,manual:true}));$('.close-button',dialog).onclick=()=>dialog.close();$('#compare-replay').onclick=()=>ds.filter(d=>d.animation).forEach(d=>d.replay());if(!ds.some(d=>d.animation))$('.compare-controls',dialog).innerHTML='<p class="small-note">見本の中を操作して比べられます。音は一つずつ再生できます。</p>'; if($('#compare-speed'))$('#compare-speed').onchange=e=>ds.forEach(d=>{if(d.animation)d.animation.playbackRate=+e.target.value});if($('#compare-same'))$('#compare-same').onchange=e=>ds.forEach(d=>d.update({duration:e.target.checked?1500:d.entry.duration}));dialog.showModal();dialog.onclose=()=>{ds.forEach(d=>{d.destroy();demos.delete(d)});dialog.innerHTML=''};}
function renderEasing(){
 main.innerHTML=`<section class="section-intro"><div class="eyebrow">EASING LAB</div><h1>同じ動き。<br>違う、心地よさ。</h1><p>同じ距離を、同じ時間で。変わるのは、進み方。<br>3つの曲線を見比べながら、自分の表現に合うイージングを選ぼう。</p></section><section class="easing-workspace" id="easing-lab" aria-label="イージング比較ラボ"></section><section class="easing-directory"><h2>${easings.length}のイージングを知る</h2><p>曲線を選ぶと、解説とコピーできるコードが開きます。</p><div class="easing-directory-grid">${easings.map(e=>`<button class="easing-index-item" data-easing-detail="${e.id}"><svg viewBox="0 0 240 180" aria-hidden="true"><path class="curve-grid" d="M24 42V142H216"/><path class="curve-line" d="${easingPath(e)}"/></svg><span><strong>${esc(e.name)}</strong><small>${esc(e.ja)}</small></span><span class="index-arrow">↗</span></button>`).join('')}</div></section>`;
 pageEffects.push(mountEasingLab($('#easing-lab'),{autoMotion}));$$('[data-easing-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.easingDetail));
}
function renderSound(){
 main.innerHTML=`<section class="section-intro"><div class="eyebrow">SOUND LIBRARY</div><h1>その一音で、<br>伝わり方が変わる。</h1><p>軽いタップ、やさしい通知、完了を知らせる響き。<br>再生ボタンを押して、音の名前と使いどころを確かめよう。</p><p class="sound-instruction">♪ 音は自動で流れません。音量を調整してお試しください。</p></section><section class="sound-directory" aria-label="音の見本"><div class="card-grid">${sounds.map(e=>`<article class="sound-card"><div class="sound-stage" data-sound="${e.id}"></div><div class="sound-meta"><h2>${esc(e.name)}</h2><p>${esc(e.ja)}</p><button class="sound-detail" data-sound-detail="${e.id}">解説・コードを見る ↗</button></div></article>`).join('')}</div></section>`;
 $$('[data-sound]').forEach(n=>createDemo(n,byId.get(n.dataset.sound),{manual:true}));$$('[data-sound-detail]').forEach(b=>b.onclick=()=>openDetail(b.dataset.soundDetail));
}
function renderColors(){
 main.innerHTML=`<section class="section-intro"><div class="eyebrow">THE COLOR STUDIO</div><h1>いい色は、組み合わせから。</h1><p>色を選んで、数値を知る。隣の色を変えて、見え方を試す。<br>配色と読みやすさを、ひとつの場所で。</p></section><div class="workspace"><section class="panel"><div class="color-stage" id="color-stage"><div class="color-letters">Aa good.</div><div class="color-caption">SAME COLOR, A DIFFERENT FEELING.</div></div><div class="code-rows" id="color-codes"></div><div class="palette-title"><span>この色から、5つの配色</span><select id="palette-mode" aria-label="配色の種類"><option value="analogous">類似色</option><option value="complementary">補色</option><option value="triad">3色の組み合わせ</option><option value="mono">同系色</option></select></div><div class="palette" id="palette"></div><p class="small-note">色を押すとHEXをコピーできます。配色はHSLから生成しています。</p><button class="secondary-button" id="copy-palette">配色のCSSをコピー ↗</button></section><aside class="panel"><h2 class="panel-title">MAKE IT YOUR COLOR</h2><div class="controls"><label class="control-field">ベースの色<div style="display:flex;gap:10px;align-items:center"><input id="base-color" type="color" value="#d9ff43"><input id="base-hex" type="text" value="#D9FF43" maxlength="7" aria-label="HEXカラーコード" spellcheck="false"></div><span class="small-note" id="hex-status" aria-live="polite">3桁または6桁のHEXを入力</span></label><label class="control-field">上に重ねる文字の色<input id="foreground-color" type="color" value="#20231e"></label><div><div class="control-label"><span>色の見本</span></div><div class="contrast-preview" id="contrast-preview">いい色には、<br>読みやすさも。</div><div class="contrast-value" id="contrast-ratio"></div><div class="contrast-badges" id="contrast-badges"></div><p class="small-note">WCAGのコントラスト比です。通常文字は4.5以上、大きな文字は3以上がAAの目安。大きな文字は約24px以上、太字なら約18.7px以上を指します。</p></div><label class="control-field">グラデーションの相手<input id="gradient-end" type="color" value="#c9b9ef"></label><div id="gradient-preview" style="height:70px;border-radius:7px"></div><button class="secondary-button" id="copy-gradient">グラデーションのCSSをコピー ↗</button><a class="small-note" href="https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html" target="_blank" rel="noopener noreferrer">読みやすさの基準を確認 ↗</a></div></aside></div>`;
 let base='#d9ff43',fg='#20231e',end='#c9b9ef',palette=[];
 const update=()=>{const rgb=rgbFromHex(base),hsl=hslFromHex(base),ok=oklchFromHex(base);const values=[['HEX',base.toUpperCase()],['RGB',`rgb(${rgb.join(' ')})`],['HSL',`hsl(${hsl[0].toFixed(1)} ${hsl[1].toFixed(1)}% ${hsl[2].toFixed(1)}%)`],['OKLCH',`oklch(${ok[0].toFixed(2)}% ${ok[1].toFixed(4)} ${ok[2].toFixed(2)})`]];$('#color-stage').style.backgroundColor=base;$('#color-stage').style.color=fg;$('#contrast-preview').style.backgroundColor=base;$('#contrast-preview').style.color=fg;$('#color-codes').innerHTML=values.map(([n,v])=>`<div class="code-row"><span>${n}</span><code>${v}</code><button data-color-copy="${v}" aria-label="${n}をコピー">↗</button></div>`).join('');$$('[data-color-copy]').forEach(b=>b.onclick=()=>copy(b.dataset.colorCopy));const ratio=contrast(base,fg);$('#contrast-ratio').textContent=`${ratio.toFixed(2)} : 1`;$('#contrast-badges').innerHTML=`<span class="badge ${ratio>=4.5?'':'neutral'}">通常文字 AA ${ratio>=4.5?'✓':'基準未満'}</span><span class="badge ${ratio>=3?'':'neutral'}">大きな文字 AA ${ratio>=3?'✓':'基準未満'}</span><span class="badge ${ratio>=7?'':'neutral'}">通常文字 AAA ${ratio>=7?'✓':'基準未満'}</span>`;const [h,s,l]=hsl,mode=$('#palette-mode').value;palette=mode==='analogous'?[-40,-20,0,20,40].map(d=>hexFromHsl(h+d,s,l)):mode==='complementary'?[hexFromHsl(h,s,Math.max(15,l-25)),base,hexFromHsl(h,s,Math.min(92,l+18)),hexFromHsl(h+180,s,l),hexFromHsl(h+180,s,Math.max(15,l-25))]:mode==='triad'?[base,hexFromHsl(h+120,s,l),hexFromHsl(h+240,s,l),hexFromHsl(h+120,s*.5,87),hexFromHsl(h+240,s*.5,22)]:[20,38,55,72,90].map(v=>hexFromHsl(h,s,v));$('#palette').innerHTML=palette.map(c=>`<button style="background:${c};color:${contrast(c,'#20231e')>contrast(c,'#ffffff')?'#20231e':'#ffffff'}" data-swatch="${c}" aria-label="${c} をコピー">${c.toUpperCase()}</button>`).join('');$$('[data-swatch]').forEach(b=>b.onclick=()=>copy(b.dataset.swatch));$('#gradient-preview').style.background=`linear-gradient(110deg,${base},${end})`};
 $('#base-color').oninput=e=>{base=e.target.value;$('#base-hex').value=base.toUpperCase();$('#hex-status').textContent='3桁または6桁のHEXを入力';update()};$('#base-hex').oninput=e=>{const v=normalizeHex(e.target.value);if(v){base=v;$('#base-color').value=v;$('#hex-status').textContent='色を反映しました';e.target.removeAttribute('aria-invalid');update()}else{e.target.setAttribute('aria-invalid','true');$('#hex-status').textContent='例 #D9FF43 または #FFF'}};$('#foreground-color').oninput=e=>{fg=e.target.value;update()};$('#gradient-end').oninput=e=>{end=e.target.value;update()};$('#palette-mode').onchange=update;$('#copy-palette').onclick=()=>copy(`:root {\n${palette.map((c,i)=>`  --color-${i+1}: ${c};`).join('\n')}\n}`);$('#copy-gradient').onclick=()=>copy(`background: linear-gradient(110deg, ${base}, ${end});`);update();
}
$('#about-button').onclick=()=>{const d=$('#about-dialog');d.innerHTML=`<div class="dialog-top"><span>ABOUT THIS PLAYGROUND</span><button class="close-button" aria-label="閉じる">×</button></div><div class="about-content"><div class="eyebrow">GOOOOOOOOOOD EXPRESSION</div><h2>あの表現に、名前がつく。</h2><p>見て、触って、覚えて、使えるWeb表現図鑑。${all.length}の独自デモを${categories.length}分野に収録しています。実際のHTML・CSS・JavaScriptを動かして、表現の名前と仕組みを結びつけます。</p><p>表現名には通称や、この図鑑で説明のためにつけた名前を含みます。各項目のリンクから実装に関係する公式資料を確認できます。ブラウザや端末によって、一部の描画や操作感は異なります。</p><p>マイコレクションと再生設定は、このブラウザに保存されます。端末間の同期は行いません。デモと掲載コードはこのサイトのオリジナルで、改変して制作に利用できます。</p><p>自動再生は画面右上から一括停止できます。OSの動きを減らす設定も初回に反映します。音のカテゴリーは再生ボタンを押すと鳴るオリジナル合成音、映像のカテゴリーは波形・字幕・画面比率などの視覚表現を扱います。</p><div class="quick-stats"><div><strong>${all.length}</strong><span>EXPRESSIONS</span></div><div><strong>${categories.length}</strong><span>CATEGORIES</span></div><div><strong>0</strong><span>EXTERNAL LIBRARIES</span></div></div><p class="small-note">Edition 02 · 2026年10月24日<br><a href="https://developer.mozilla.org/ja/docs/Web" target="_blank" rel="noopener noreferrer">MDN Web Docs ↗</a> · <a href="https://www.w3.org/TR/WCAG22/" target="_blank" rel="noopener noreferrer">WCAG 2.2 ↗</a></p></div>`;$('.close-button',d).onclick=()=>d.close();d.showModal()};
